with base as (select *, cast(txn_time as date) txn_time_day from transactions where txn_time >= to_timestamp('2023-08-28 21:00:00') and merchant is not null), with_gaps as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time asc, id asc) > interval 14 days then 1 else 0 end as is_new_session from base), sessionized as (select id, txn_type, amount, txn_time, merchant, is_flagged, sum(is_new_session) over (partition by merchant order by txn_time asc, id asc rows between unbounded preceding and current row) as session_no from with_gaps) select date_trunc('month', txn_time) as activity_month, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as span_minutes, min(session_no) as min_session_no, round(sum(amount) / nullif(count(case when merchant = 'Amazon' then 1 end), 0), 2) as amount_per_amazon from sessionized group by date_trunc('month', txn_time) having (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 > 0 order by span_minutes desc nulls last;
